 if(knowledgeId)return knowledgeDetail();
 const area=state.knowledgeAreas.find(a=>a.id===catalogArea);
 const filtered=state.knowledgeItems.filter(k=>(!catalogArea||k.area_id===catalogArea)&&matchesQuery(`${k.name} ${state.knowledgeAreas.find(a=>a.id===k.area_id)?.name} ${knowledgeGuide(k).description}`,catalogQuery));
 return heading('CATÁLOGO DA MIND','Conhecimentos','Encontre um tema, conheça aplicações e descubra o que sua equipe já compartilhou.',button('+ Novo conhecimento','catalog-new','','primary'))+
 `<form data-form="catalog-search" class="catalog-search"><label class="sr-only" for="catalog-query">Pesquisar área ou conhecimento</label><input id="catalog-query" name="q" type="search" value="${esc(catalogQuery)}" placeholder="Busque uma área ou conhecimento, como projetos ou JavaScript"><button class="primary">Pesquisar</button></form><div class="catalog-layout"><aside class="card catalog-areas"><h2>Áreas do conhecimento</h2><p class="meta">${state.knowledgeAreas.length} áreas · ${state.knowledgeItems.length} conhecimentos</p>${button('Todos os conhecimentos','catalog-area','data-id=""',!catalogArea?'active':'')}${state.knowledgeAreas.map(a=>button(`${esc(a.name)} <small>${state.knowledgeItems.filter(k=>k.area_id===a.id).length}</small>`,'catalog-area',`data-id="${esc(a.id)}"`,a.id===catalogArea?'active':'')).join('')}</aside><section><div class="row between catalog-summary"><div><h2>${esc(area?.name||'Explore o catálogo')}</h2><p class="meta">${filtered.length} conhecimentos${catalogQuery?' encontrados':''}</p></div>${catalogArea||catalogQuery?button('Limpar filtros','catalog-clear'):''}</div><div class="knowledge-grid">${filtered.slice(0,catalogLimit).map(k=>{const guide=knowledgeGuide(k),count=state.postKnowledge.filter(p=>p.knowledge_id===k.id).length;return `<button class="card knowledge-card" data-action="knowledge-detail" data-id="${esc(k.id)}"><span class="eyebrow">${esc(state.knowledgeAreas.find(a=>a.id===k.area_id)?.name)}</span><h3>${esc(k.name)}</h3><p class="muted">${esc(guide.description||'Conhecimento adicionado pela comunidade. Abra para consultar os relatos.')}</p><span class="meta">${count} ${count===1?'publicação disponível':'publicações disponíveis'} · ${k.source==='catalog'?'Catálogo MIND':'Comunidade'}</span></button>`;}).join('')||'<div class="card empty"><h2>Nenhum conhecimento encontrado</h2><p>Tente outra palavra ou cadastre um novo conhecimento.</p></div>'}</div>${filtered.length>catalogLimit?button('Carregar mais conhecimentos','catalog-more','','search-more'):''}</section></div>`;
