 const k=state.knowledgeItems.find(k=>k.id===knowledgeId);if(!k)return '<div class="empty">Conhecimento indisponível.</div>';
 const area=state.knowledgeAreas.find(a=>a.id===k.area_id),guide=knowledgeGuide(k),intel=knowledgeNetwork?.concepts.find(c=>c.knowledge_ids?.includes(k.id)||c.knowledge_id===k.id);
 const ids=new Set(state.postKnowledge.filter(p=>p.knowledge_id===k.id).map(p=>p.post_id));
