 return `${button('← Voltar ao catálogo','catalog-back','','back-button')}`+heading(esc(area?.name||'CONHECIMENTO'),esc(k.name),'',button('Publicar sobre este tema','knowledge-post',`data-id="${esc(k.id)}"`,'primary'))+
 `<div class="knowledge-detail-layout"><div class="stack"><section class="card"><div class="row between"><h2>Sobre este conhecimento</h2><span class="pill">${k.source==='catalog'?'Catálogo MIND':'Comunidade'}</span></div><p class="body">${esc(guide.description||'A descrição ainda não foi adicionada.')}</p><h3>Exemplos práticos</h3>${guide.examples.length?`<ul class="examples-list">${guide.examples.map(ex=>`<li>${esc(ex)}</li>`).join('')}</ul><p class="meta">Exemplos ilustrativos. Os relatos da empresa estão nas publicações abaixo.</p>`:'<p class="muted">Ainda não há exemplos explicativos cadastrados.</p>'}${user.is_admin||k.created_by===user.id?button('Editar descrição e exemplos','knowledge-edit',`data-id="${esc(k.id)}"`):''}</section>${intel?`<section class="card knowledge-intelligence-card">${renderRiskEvidence(intel)}<h3>Áreas relacionadas no catálogo</h3><div class="row knowledge-tags">${intel.primaryAreas.map(a=>`<span class="pill">${esc(a.name)}</span>`).join('')}</div><p class="meta">Agrupamento para descoberta. Não significa que esse conhecimento seja necessário à empresa. A análise usa declarações e publicações visíveis para sua conta.</p></section>`:'<section class="card"><h2>Riscos do conhecimento</h2><p class="muted">Este item está no catálogo, sem evidências disponíveis na empresa para esta análise. Ele não gera alerta nem entra no ranking de riscos.</p></section>'}<section class="stack"><h2>Publicações sobre ${esc(k.name)} · ${posts.length}</h2><p class="meta">Inclui todos os feeds que sua conta pode acessar.</p>${posts.slice(0,detailLimit).map(postCard).join('')||'<div class="card empty"><h2>Compartilhe a primeira experiência</h2><p>Conte como este conhecimento foi aplicado no trabalho.</p></div>'}${posts.length>detailLimit?button('Carregar mais publicações','knowledge-posts-more'):''}</section></div><aside class="stack knowledge-people"><section class="card"><h2>Quem já compartilhou</h2><p class="meta">Pessoas com publicações disponíveis sobre este tema.</p>${people.map(p=>personCard(p,`<span class="pill">${posts.filter(post=>post.user_id===p.id).length} publicações</span>`)).join('')||'<p class="muted">Nenhum relato disponível ainda.</p>'}</section><section class="card"><h2>Indicado nos perfis</h2><p class="meta">Conhecimento selecionado pela própria pessoa.</p>${declared.map(p=>personCard(p)).join('')||'<p class="muted">Ninguém selecionou este tema no perfil ainda.</p>'}</section></aside></div>`;
