function guidePage(){
 const sections=[
  ['Compartilhe experiências que ajudem','Conte o contexto, o desafio, o que foi feito e o aprendizado. Inclua um título que ajude outras pessoas a encontrar o assunto. Para projetos, use o nome do projeto no título ou no texto.'],
  ['Organize os conhecimentos','Associe de 1 a 8 conhecimentos relevantes a cada publicação. Pesquise no catálogo antes de criar um novo termo e escolha a área correspondente. Novos conhecimentos ficam disponíveis imediatamente.'],
  ['Encontre o que precisa','A pesquisa geral procura publicações, comentários, pessoas e conhecimentos. Use filtros e coloque uma expressão entre aspas para procurar a frase exata, como “Projeto Aurora”.'],
  ['Escolha o público com atenção','Selecione o feed adequado à conversa. Os acessos seguem o setor e o nível do cargo. Os perfis e as páginas dos conhecimentos exibem apenas as publicações disponíveis para quem está consultando.'],
  ['Cuide das informações','Compartilhe apenas informações que podem circular no público escolhido. Evite senhas, dados pessoais desnecessários e documentos confidenciais. Use os canais internos adequados para assuntos restritos.'],
  ['Converse com respeito e dê contexto','Reconheça contribuições, faça perguntas e dê crédito às fontes. Diferencie uma hipótese de um resultado observado e atualize seus relatos quando surgirem novos aprendizados.']
 ];
 return heading('ORIENTAÇÕES PARA A EQUIPE','Guia da MIND','Um ponto de consulta para compartilhar e encontrar conhecimento.',user.is_admin?button('Editar orientações da empresa','guide-edit','','primary'):'')+`<div class="guide-grid">${sections.map(([name,body],i)=>`<section class="card"><span class="guide-number">0${i+1}</span><h2>${name}</h2><p>${body}</p></section>`).join('')}</div><section class="card dashboard-section"><h2>Orientações de ${esc(state.company.name)}</h2>${state.guide.body?`<p class="body">${esc(state.guide.body)}</p><p class="meta">Atualizado em ${date(state.guide.updated_at)} por ${esc(state.guide.updated_by)}.</p>`:'<p class="muted">A administração ainda não adicionou orientações específicas da empresa.</p>'}</section>`;
}
